'use strict';

// MODULES //

var tape = require( 'tape' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var BigInt = require( '@stdlib/bigint/ctor' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var isEqual = require( '@stdlib/number/uint64/base/assert/is-equal' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var rightShift = require( './../lib' );


// VARIABLES //

// Shift mask: 0x3f => 00000000000000000000000000111111
var MAX_SHIFT = 63 >>> 0;

var opts = {
	'skip': !hasBigIntSupport()
};


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rightShift, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function performs bitwise shift to the right on a 64-bit unsigned integer', function test( t ) {
	var expected;
	var out;
	var a;

	// Zero shift:
	a = new Uint64( 1234 );
	out = rightShift( a, 0 );
	expected = new Uint64( 1234 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	// Small shift:
	a = new Uint64( 1234 );
	out = rightShift( a, 1 );
	expected = new Uint64( 617 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	a = new Uint64( 1234 );
	out = rightShift( a, 2 );
	expected = new Uint64( 308 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	a = new Uint64( 0xffffffff );
	out = rightShift( a, 31 );
	expected = new Uint64( 1 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	// Large shift:
	a = new Uint64( 0xffffffff );
	out = rightShift( a, 32 );
	expected = new Uint64( 0 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	a = new Uint64( 9876543210 );
	out = rightShift( a, 32 );
	expected = new Uint64( 2 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	a = Uint64.of( 0x12345678, 0x90abcdef );
	out = rightShift( a, 48 );
	expected = Uint64.of( 0, 0x1234 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	a = Uint64.of( 0xffffffff, 0xffffffff );
	out = rightShift( a, 63 );
	expected = Uint64.of( 0, 1 );
	t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function performs bitwise shift to the right on a 64-bit unsigned integer (random values)', opts, function test( t ) {
	var big64shifted;
	var expected;
	var values;
	var shift;
	var out;
	var a;
	var x;
	var i;

	x = discreteUniform( 100, 0, UINT32_MAX, {
		'dtype': 'uint32'
	});
	values = [];
	for ( i = 0; i < x.length; i++ ) {
		values.push( Uint64.of( x[ i ], x[ (i+1)%x.length ] ) );
	}

	for ( i = 0; i < values.length; i++ ) {
		a = values[ i ];
		for ( shift = 0; shift < 64; shift++ ) {
			out = rightShift( a, shift );
			big64shifted = BigInt.asUintN( 64, a.valueOf() >> BigInt( shift ) );
			expected = new Uint64( big64shifted );
			t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );
		}
	}

	t.end();
});

tape( 'if provided a shift less than `0` or greater than `63`, the function performs a bitwise right shift based on the `6` least significant bits', function test( t ) {
	var expected;
	var shift;
	var out;
	var a;

	a = Uint64.of( 0x12345678, 0x90abcdef );

	for ( shift = -100; shift < 0; shift++ ) {
		out = rightShift( a, shift );
		expected = rightShift( a, shift&MAX_SHIFT );
		t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );
	}
	for ( shift = 64; shift < 150; shift++ ) {
		out = rightShift( a, shift );
		expected = rightShift( a, shift&MAX_SHIFT );
		t.strictEqual( isEqual( out, expected ), true, 'returns expected value' );
	}
	t.end();
});
